/**
 * The Basic Reading scope and sequence: 202 skills across 11 sections, levels 1-4.
 *
 * Extracted from the Lesson Filer design canvas rather than retyped, so the
 * ordering, the section names and the material lists are exactly what was
 * authored there. Sections are listed in teaching order and the page groups by
 * walking this array, so the order here is the order on screen.
 *
 * Every skill now carries a workbook and a workbook key; 133 also have a
 * lesson and answer key, and five have slides and a maze packet. The hrefs are
 * the canvas's own relative paths, and the files sit under the same paths in
 * content-reading-materials/, served through /api/reading/materials so they
 * are readable only by someone with an account.
 *
 * The canvas lists five skills twice over, with identical links each time — ey,
 * ow, oo, ie and -ure. The repeats are dropped here, which is why the ids skip
 * 80, 85, 87, 123 and 179. Ids are otherwise the canvas's own, so taught marks
 * already saved in a browser keep pointing at the skills they were set on.
 */

export interface LessonLink {
  label: string
  href: string
}

export interface Lesson {
  id: number
  level: number
  section: string
  skill: string
  links: LessonLink[]
}

/** The 11 sections, in teaching order. */
export const SECTIONS = [
  "My First Sounds — Group 1",
  "My First Sounds — Group 2",
  "Building Words",
  "Silent e & Word Endings",
  "Longer Words & Endings",
  "Vowel Teams & Bossy R",
  "Open Syllables & Soft Sounds",
  "Trickier Teams & Endings",
  "Word Roots",
  "More Roots & Latin Endings",
  "Really Big Words"
]

